let reduceMotion = false;
try { reduceMotion = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (err) { reduceMotion = false; }
const tone = (f, d, o) => { try { api.tone(f, d, o); } catch (err) { /* sound is optional */ } };
const noise = (d, o) => { try { api.noise(d, o); } catch (err) { /* sound is optional */ } };
const nowMs = () => (window.performance && performance.now ? performance.now() : Date.now());
const readBest = () => { try { const b = api.best(); return typeof b === 'number' && isFinite(b) ? b : null; } catch (err) { return null; } };

let vs = 1, vox = 0, voy = 0, dpr = 1, cssW = 0, cssH = 0, layerK = 0;
