g.fillStyle = gr; g.fillRect(0, 0, W, H);
g.fillStyle = 'rgba(31,216,255,0.06)';
for (let x = 10; x < W; x += 20) for (let y = 10; y < H; y += 20) g.fillRect(x, y, 1, 1);
