const save = { s: [], fr: 0, fd: 0 };
for (let i = 0; i < LEVELS.length; i++) save.s.push(0);
(function loadSave() {
try {
const raw = api.load ? api.load('progress') : null;
if (!raw) return;
const d = JSON.parse(raw);
if (!d || typeof d !== 'object') return;
if (Array.isArray(d.s)) for (let i = 0; i < save.s.length && i < d.s.length; i++) { const v = d.s[i] | 0; save.s[i] = v >= 0 && v <= 7 ? v : 0; }
if (isFinite(d.fr) && d.fr > 0) save.fr = Math.min(9999999, Math.floor(d.fr));
if (isFinite(d.fd) && d.fd > 0) save.fd = Math.min(9999, Math.floor(d.fd));
} catch (err) { /* corrupt save: start fresh */ }
})();
function persist() { try { if (api.save) api.save('progress', JSON.stringify(save)); } catch (err) { /* storage blocked */ } }
