function sectorStars(k) { let t = 0; for (let i = k * 10; i < k * 10 + 10; i++) t += starsOf(save.s[i]); return t; }
const sectorOpen = k => totalStars() >= SECTORS[k].need;
const levelOpen = i => sectorOpen((i / 10) | 0) && (i % 10 === 0 || (save.s[i - 1] & 1) !== 0);
const freeOpen = () => (save.s[9] & 1) !== 0;

let sfxGate = 0;
