function sfxSpot() { tone(700, 0.08, { type: 'square', vol: 0.05 }); tone(700, 0.08, { type: 'square', vol: 0.05, delay: 0.12 }); }
function sfxLock() { tone(110, 0.6, { type: 'sawtooth', vol: 0.08, slide: 220 }); tone(116, 0.6, { type: 'sawtooth', vol: 0.05 }); noise(0.4, { vol: 0.08, filter: 800 }); }
