box.style.cssText = 'position:absolute;left:0;top:0;right:0;bottom:0;display:flex;align-items:center;justify-content:center;' +
'padding:24px;box-sizing:border-box;text-align:center;background:#2a1a14;color:#C9D3E3;font:600 17px ' + FONT_B + ';';
box.textContent = msg;
root.appendChild(box);
