tree(st, -4, 4.2, 1); tree(st, -3.2, -4.6, 0.85); tree(st, 2.5, -5.2, 0.7);
plat(st, 10.5, 0, 0.5, 4, 4, 0);
plat(st, 15.5, 1.5, 1.2, 4, 4, 1);
