plat(st, 7.5, 0, 0, 1.2, 8, 0);
plat(st, 14, 0, 0.6, 4, 4, 1);
tile(st, 19, -1, 1.0, 2.6); tile(st, 23, 1, 1.0, 2.6); tile(st, 27, -1, 1.0, 2.6);
plat(st, 32.5, 0, 1.4, 5, 5, 2); sweeper(st, 32.5, 0, 1.4, 4.6, 1.4);
mover(st, 40, 0, 1.8, 3, 3, { type: 'circle', R: 2.5, T: 6 });
plat(st, 47, 0, 2.4, 4, 4, 0);
plat(st, 54, 0, 2.4, 5, 7, 1); lava(st, 54, 0, 2.4, 5, 1.2);
disc(st, 62.5, 0, 3.0, 3, 1.2);
plat(st, 70, 0, 3.0, 1.0, 6, 2);
plat(st, 76, 1.5, 3.6, 1.0, 5, 0);
plat(st, 83, 0, 3.6, 4, 4, 1); pad(st, 83, 0, 3.6);
plat(st, 89, 0, 8.0, 5, 4, 2);
