if (Math.abs(dy) > p.hy + r) return false;
const rd2 = dx * dx + dz * dz;
if (rd2 > (R + r) * (R + r)) return false;
const rd = Math.sqrt(rd2);
let qx = dx, qz = dz;
if (rd > R) { qx = dx / rd * R; qz = dz / rd * R; }
let nx = dx - qx, ny = dy - clamp(dy, -p.hy, p.hy), nz = dz - qz;
const d2 = nx * nx + ny * ny + nz * nz;
if (d2 > r * r) return false;
