for (let i = 0; i < 5; i++) overCmp[i] = saved.splits[i];
prevBestTotal = saved.total;
if (!submitted) { submitted = true; newBest = !!api.submit(finalScore); }
saved.total = prevBestTotal === null ? runT : Math.min(prevBestTotal, runT);
for (let i = 0; i < 5; i++) if (splits[i] > 0) saved.splits[i] = saved.splits[i] === null ? splits[i] : Math.min(saved.splits[i], splits[i]);
try { if (typeof api.save === 'function') api.save('bests', JSON.stringify(saved)); } catch (err) { /* storage blocked */ }
refreshBest();
