if (bridgeOn) stopBridge();
launchConfetti();
overYaw = camYaw + Math.PI;
const notes = [523, 659, 784, 1046];
for (let i = 0; i < notes.length; i++) api.tone(notes[i], i === 3 ? 0.4 : 0.14, { type: 'triangle', vol: 0.13, delay: i * 0.12 });
api.noise(0.3, { vol: 0.06, filter: 4000, delay: 0.36 });
