if (rem <= 0.05) { v = 0; R.s = Math.min(R.s, stopS); if (!R.done) R.done = 'station'; }
else { const vt = Math.max(1.0, Math.sqrt(6 * rem)); if (v > vt) v = Math.max(vt, v - 25 * dt); else if (v < 1.0) v = Math.min(1.0, v + 3 * dt); }
