if (!path.complete && R.s >= path.len - 0.4) { R.s = path.len - 0.4; R.v = 0; if (!R.done) R.done = 'buffer'; }
if (R.s - 1.6 - (CARS - 1) * CAR_GAP - 1.6 < 0.2) { R.s = 3.4 + (CARS - 1) * CAR_GAP; R.v = 0; if (!R.done) R.done = 'stall'; }
