let mode = 'title', sub = 'build', menu = null, paused = false;
let overAt = 0, overT = 0, animT = 0, lastT = performance.now(), raf = 0, destroyed = false;
let touchMode = !!api.isTouch, shakeAmt = 0, camSmoothInit = false, camSnapToEnd = false;
let titleSel = 1, menuSel = 0, hasWork = false, best = api.best();
let toastMsg = '', toastCol = UI.hi, toastT = 0, toastDur = 2;
let trackLen = 0, maxH = 0;
const cam = { yaw: -2.25, pitch: 0.6, dist: 75 };
const camTgt = new THREE.Vector3(PLOT / 2, 0, PLOT / 2), camPos = new THREE.Vector3();
const camFwdS = new THREE.Vector3(1, 0, 0), camUpS = new THREE.Vector3(0, 1, 0);
let titleYaw = -2.0;

function toast(msg, col, dur) { toastMsg = msg; toastCol = col || UI.hi; toastDur = dur || 2.2; toastT = toastDur; }
