toast('Circuit complete - press V to ride', UI.ok, 3.2);
[523, 659, 784, 1047].forEach(function (f, i) { api.tone(f, 0.16, { type: 'triangle', vol: 0.1, delay: 0.08 + i * 0.09 }); });
burst(SX0 + 4, 3, SZC, 40, 0xffc93c, 9, 1);
