function orbitCam(dt, follow) {
const k = follow > 0 ? 1 - Math.exp(-dt * follow) : 1;
camTgt.x += (V4.x - camTgt.x) * k; camTgt.y += (V4.y - camTgt.y) * k; camTgt.z += (V4.z - camTgt.z) * k;
const cp = Math.cos(cam.pitch);
camera.position.set(camTgt.x + cp * Math.cos(cam.yaw) * cam.dist, camTgt.y + Math.sin(cam.pitch) * cam.dist, camTgt.z + cp * Math.sin(cam.yaw) * cam.dist);
const gy = groundH(camera.position.x, camera.position.z) + 2;
if (camera.position.y < gy) camera.position.y = gy;
camera.up.set(0, 1, 0);
camera.lookAt(camTgt);
}
function setFov(f) { if (camera.fov !== f) { camera.fov = f; camera.updateProjectionMatrix(); } }
function rideCamera(dt) {
if (rideCam === 0) { // front-seat POV with the bank roll eased in
lookVec(path.pos, ride.s - 1.2, CP, false); lookVec(path.tan, ride.s + 2.5, CT, true); lookVec(path.up, ride.s - 1.2, CU, true);
if (!camSmoothInit) { camFwdS.copy(CT); camUpS.copy(CU); camSmoothInit = true; }
camFwdS.lerp(CT, 1 - Math.exp(-dt * 10));
if (camFwdS.lengthSq() < 1e-6) camFwdS.copy(CT);
camFwdS.normalize();
camUpS.lerp(CU, 1 - Math.exp(-dt * 5));
camUpS.addScaledVector(camFwdS, -camUpS.dot(camFwdS));
if (camUpS.lengthSq() < 1e-6) camUpS.copy(CU);
camUpS.normalize();
CR3.crossVectors(camFwdS, camUpS);
V1.copy(camFwdS).negate();
M4.makeBasis(CR3, camUpS, V1);
camera.quaternion.setFromRotationMatrix(M4);
camera.position.copy(CP).addScaledVector(CU, 1.75).addScaledVector(CT, 0.3);
setFov(76);
} else if (rideCam === 1) { // chase
const rs = carS(CARS - 1) - 2;
lookVec(path.pos, rs, V2, false); lookVec(path.tan, rs, V3, true);
V4.copy(V2).addScaledVector(V3, -11); V4.y += 5.5;
if (!camSmoothInit) { camPos.copy(V4); camSmoothInit = true; }
camPos.lerp(V4, 1 - Math.exp(-dt * 4));
camera.position.copy(camPos);
const gy = groundH(camPos.x, camPos.z) + 1.5;
if (camera.position.y < gy) camera.position.y = gy;
lookVec(path.pos, ride.s - 4, V2, false);
camera.up.set(0, 1, 0); camera.lookAt(V2);
setFov(62);
} else { // trackside poles
const c = clamp(Math.floor((ride.s + 10) / 60), 0, path.ncams - 1);
const x = path.cams[c * 3], z = path.cams[c * 3 + 2];
camera.position.set(x, Math.max(path.cams[c * 3 + 1], groundH(x, z) + 2.5), z);
lookVec(path.pos, ride.s - 6, V2, false);
camera.up.set(0, 1, 0); camera.lookAt(V2);
setFov(55);
}
}
function placeTrain() {
const riding = ride.on && path;
for (let c = 0; c < CARS; c++) {
if (riding) { const s = carS(c); lookVec(path.pos, s, CP, false); lookVec(path.tan, s, CT, true); lookVec(path.up, s, CU, true); }
else { CP.set(SX0 + TRAIN_START - 1.6 - c * CAR_GAP, BASE, SZC); CT.set(1, 0, 0); CU.set(0, 1, 0); }
CU.addScaledVector(CT, -CU.dot(CT));
if (CU.lengthSq() < 1e-6) CU.set(0, 1, 0);
CU.normalize();
CR3.crossVectors(CT, CU);
M4.makeBasis(CT, CU, CR3);
cars[c].quaternion.setFromRotationMatrix(M4);
cars[c].position.copy(CP);
const gy = Math.max(0, groundH(CP.x, CP.z)), sc = clamp(1 - (CP.y - gy) / 50, 0.35, 1);
DUMMY.position.set(CP.x, gy + 0.1, CP.z); DUMMY.rotation.set(0, Math.atan2(-CT.z, CT.x), 0); DUMMY.scale.set(sc, 1, sc);
DUMMY.updateMatrix(); blobs.setMatrixAt(c, DUMMY.matrix);
}
blobs.instanceMatrix.needsUpdate = true;
}

const keys = {};
function update(dt) {
animT += dt;
if (toastT > 0) toastT -= dt;
if (shakeAmt > 0) shakeAmt = Math.max(0, shakeAmt - dt * 2.5);
updateConfetti(dt);
if (mode === 'over') overT += dt;
if (paused) return;
if (stallMark > 0) stallMark -= dt;
if (ride.on && path) {
if (!ride.done) {
ride.acc += dt;
let steps = 0;
while (ride.acc >= SUB && steps < 8 && !ride.done) { rideStep(SUB); ride.acc -= SUB; steps++; }
if (steps >= 8) ride.acc = 0;
if (ride.t > 240 && !ride.done) ride.done = 'stall';
rideFx(dt);
} else {
ride.doneT += dt;
if (ride.doneT > (ride.done === 'stall' ? 0.3 : 0.9)) finishRide();
}
}
updateParticles(dt);
if (mode !== 'title' && !(mode === 'playing' && sub === 'ride') && !menu) {
const yi = (keys.KeyE ? 1 : 0) - (keys.KeyQ ? 1 : 0);
const pi = (keys.KeyR || keys.ArrowUp ? 1 : 0) - (keys.KeyF || keys.ArrowDown ? 1 : 0);
const zi = (keys.KeyX ? 1 : 0) - (keys.KeyZ ? 1 : 0);
cam.yaw += yi * 1.7 * dt;
cam.pitch = clamp(cam.pitch + pi * 1.1 * dt, 0.08, 1.45);
cam.dist = clamp(cam.dist * Math.exp(zi * 1.4 * dt), 16, 260);
}
}

function render(dt) {
const building = mode === 'playing' && sub === 'build';
ghost.mesh.visible = building && !complete;
ghostTiles.visible = building && !complete;
endArrow.visible = building && !complete;
bufferStop.visible = pieces.length > 0 && !complete;
if (building) {
ghostMat.opacity = 0.36 + 0.14 * Math.sin(animT * 5);
endArrow.position.set(endPos.x, endPos.y + 3.2 + Math.sin(animT * 4) * 0.35, endPos.z);
}
placeTrain();
if (mode === 'title') {
titleYaw += dt * 0.06;
V4.set(PLOT / 2, 8, PLOT / 2 - 10);
const d = 205, cp = Math.cos(0.42);
camera.position.set(V4.x + cp * Math.cos(titleYaw) * d, V4.y + Math.sin(0.42) * d, V4.z + cp * Math.sin(titleYaw) * d);
camera.up.set(0, 1, 0); camera.lookAt(V4);
setFov(55);
} else if (mode === 'playing' && sub === 'ride' && ride.on && path) {
rideCamera(dt);
} else {
if (mode === 'over') cam.yaw += dt * 0.07;
if (stallMark > 0) V4.copy(stallPos); else V4.copy(endPos);
if (camSnapToEnd) { camTgt.copy(V4); camSnapToEnd = false; }
orbitCam(dt, 5);
setFov(60);
}
if (shakeAmt > 0 && !paused) {
const a = shakeAmt * 0.35;
camera.position.x += (Math.random() * 2 - 1) * a; camera.position.y += (Math.random() * 2 - 1) * a; camera.position.z += (Math.random() * 2 - 1) * a;
}
sky.position.copy(camera.position);
renderer.render(scene, camera);
drawHUD();
}

let cw = 1, ch = 1, hudDpr = 1, hs = 1, LW = 960, LH = 600, mx = -1, my = -1;
const BTN_MAX = 56, bx = new Float32Array(BTN_MAX), by = new Float32Array(BTN_MAX), bw = new Float32Array(BTN_MAX), bh = new Float32Array(BTN_MAX);
