const UI_GS = [['leave', 'Leave room', 365, 404, 230, 52, 0]];
const UI_MENU = [['resume', 'Resume', 292, 330, 180, 50, 1], ['leave', 'Leave match', 488, 330, 180, 50, 0]];
const UI_RES = [['again', 'REMATCH', 252, 450, 220, 52, 1], ['leave', 'LEAVE', 488, 450, 220, 52, 0]];

function hNow() { let t = NaN; try { t = +N.s.hostTime(); } catch (e) { /* closing */ } return isFinite(t) ? t : performance.now(); }
