c.strokeStyle = '#FFC93C'; c.lineWidth = 1.2; c.stroke();
c.fillStyle = '#FFC93C'; c.fillRect(-7, -1.2, 1, 5.4); c.fillRect(-9.2, 1, 5.4, 1);
c.fillStyle = '#eef3fa'; // sword
c.beginPath(); c.moveTo(7, 1); c.lineTo(7, -9); c.lineTo(7.9, -11.5); c.lineTo(8.8, -9); c.lineTo(8.8, 1); c.closePath(); c.fill();
c.fillStyle = 'rgba(120,140,170,0.6)'; c.fillRect(7.8, -9, 0.5, 9.5);
c.fillStyle = '#FFC93C'; c.fillRect(5.4, 1, 5, 1.6);
c.fillStyle = '#6b4226'; c.fillRect(7.2, 2.6, 1.4, 3);
c.fillStyle = '#b8c3d4'; circ(c, 7.9, 3.4, 1.5); c.fill();
const hg = c.createLinearGradient(0, -12.5, 0, -3); // helmet
hg.addColorStop(0, '#f1f4f9'); hg.addColorStop(1, '#7d8aa0');
circ(c, 0, -7.5, 5); c.fillStyle = hg; c.fill();
c.strokeStyle = 'rgba(20,24,36,0.5)'; c.lineWidth = 0.7; c.stroke();
c.fillStyle = '#151824'; rr(c, -0.5, -8.6, 5.2, 1.8, 0.9); c.fill();
c.fillStyle = '#e8484f'; // plume
