showBanner(P.cpu ? P.name + ' takes ' + grpName(P.grp) : 'You are ' + grpName(P.grp), (P.cpu ? 'You have ' + grpName(other.grp) : 'Pot all 7, then call and pot the 8'), UI.hi, 2.4);
