const top = cy + steps * 0.4, z1 = cz + steps * 0.9;
slab(-hw, hw, z1, z1 + 4, top);
if (L.theme.ground) laneWalls(cz, z1 + 4, hw, cy); else sides(z1, z1 + 4, hw, top);
for (let i = 0; i < steps; i += 2) glow(hw * 2, 0.04, 0.06, 0, cy + (i + 1) * 0.4 + 0.02, cz + i * 0.9 + 0.04, L.theme.neonA);
