g.addColorStop(0, 'rgba(255,214,140,0.95)'); g.addColorStop(0.12, 'rgba(255,140,70,0.55)'); g.addColorStop(1, 'rgba(255,90,40,0)');
ctx.fillStyle = g; ctx.fillRect(0, 0, w, hz + 1);
