for (let i = 0; i < sk.length; i += 2) {
const bx = sk[i] * w, bw = w * 0.045, bh = sk[i + 1] * h;
poly([bx, hz, bx, hz - bh, bx + bw * 0.4, hz - bh - 6, bx + bw * 0.7, hz - bh + 4, bx + bw, hz - bh * 0.8, bx + bw, hz], '#2a0f16');
}
poly([0, hz - 34, w * 0.3, hz - 30, w * 0.33, hz - 22, w * 0.31, hz - 18, 0, hz - 22], '#351319');
poly([w * 0.06, hz - 22, w * 0.08, hz - 22, w * 0.08, hz, w * 0.06, hz], '#351319');
poly([w * 0.2, hz - 20, w * 0.22, hz - 20, w * 0.22, hz, w * 0.2, hz], '#351319');
