for (let i = 0; i < far.length; i++) zomb(far[i][0] * w, far[i][1] * h, far[i][2], 0, '#1d0d10');
ctx.save(); ctx.translate(w * 0.44, h * 0.6); ctx.scale(1.25, 1.25);
poly([-9, 0, -6, -14, 6, -14, 9, 0, 4, 0, 0, -8, -4, 0], '#170a0c');
poly([-12, -14, 12, -14, 10, -32, -10, -32], '#170a0c');
