g = ctx.createLinearGradient(0, h * 0.66, 0, h);
g.addColorStop(0, 'rgba(255,236,180,0.32)'); g.addColorStop(1, 'rgba(255,236,180,0)');
poly([w * 0.36, h * 0.69, w * 0.42, h * 0.69, w * 0.36, h, w * 0.02, h], g);
poly([w * 0.58, h * 0.69, w * 0.64, h * 0.69, w * 0.98, h, w * 0.64, h], g);
