ctx.beginPath();
for (let i = -2; i <= 2; i++) { ctx.moveTo(cx + i * 22, by - 142); ctx.lineTo(cx + i * 25, by - 104); }
ctx.stroke();
poly([cx - 52, by - 142, cx - 10, by - 142, cx - 30, by - 104, cx - 62, by - 104], 'rgba(255,170,110,0.12)');
poly([cx - 46, by - 88, cx + 46, by - 88, cx + 42, by - 50, cx - 42, by - 50], '#2a2a2e');
ctx.strokeStyle = '#4a4a50'; ctx.lineWidth = 2;
ctx.beginPath();
for (let i = 0; i < 5; i++) { ctx.moveTo(cx - 44, by - 82 + i * 7); ctx.lineTo(cx + 44, by - 82 + i * 7); }
ctx.stroke();
ctx.save(); ctx.shadowColor = '#fff2c0'; ctx.shadowBlur = 24;
ctx.fillStyle = '#fff6da';
ctx.beginPath(); ctx.arc(cx - 66, by - 70, 9, 0, TAU); ctx.arc(cx + 66, by - 70, 9, 0, TAU); ctx.fill();
ctx.fillStyle = '#ffd27a';
ctx.fillRect(cx - 40, by - 158, 80, 6);
ctx.restore();
poly([cx - 124, by - 52, cx, by - 30, cx + 124, by - 52, cx + 118, by - 4, cx, by + 6, cx - 118, by - 4], '#4b4e55');
poly([cx - 124, by - 52, cx, by - 30, cx + 124, by - 52, cx + 122, by - 44, cx, by - 22, cx - 122, by - 44], '#7b8088');
const plowTop = function (x) { return by - 52 + (1 - Math.min(1, Math.abs(x - cx) / 124)) * 22; };
for (let i = 0; i < 8; i++) {
const sx = cx - 112 + i * 32;
if (i % 2 === 0) poly([sx, plowTop(sx) + 7, sx + 14, plowTop(sx + 14) + 7, sx + 8, by - 6, sx - 6, by - 8], 'rgba(230,170,40,0.75)');
}
for (let i = 0; i < 9; i++) {
const sx = cx - 116 + i * 29, sy = plowTop(sx) + 3;
poly([sx - 6, sy, sx + 6, sy, sx, sy - 22], '#a6abb3');
}
