poly([cx + 8, by - 172, cx + 86, by - 190, cx + 88, by - 182, cx + 10, by - 164], '#55585f');
ctx.save(); ctx.globalCompositeOperation = 'lighter';
ctx.strokeStyle = 'rgba(255,210,120,0.9)'; ctx.lineWidth = 3;
