'uniform sampler2D tDiffuse;',
'uniform float uTime;',
'uniform float uGlitch;',
'uniform float uFade;',
'uniform float uVig;',
'uniform float uGrain;',
'uniform vec3 uTint;',
'uniform float uTintAmt;',
'varying vec2 vUv;',
