const LISTENERS = [
[window, 'keydown', onKeyDown], [window, 'keyup', onKeyUp], [window, 'blur', onBlur],
[document, 'visibilitychange', onVisibility],
[canvas, 'pointerdown', onPointerDown], [canvas, 'pointermove', onPointerMove], [canvas, 'pointerup', onPointerUp],
[canvas, 'pointercancel', onPointerUp], [canvas, 'contextmenu', onContextMenu],
];
let ro = null;
if (typeof ResizeObserver !== 'undefined') { ro = new ResizeObserver(function () { resize(); }); ro.observe(root); }
else LISTENERS.push([window, 'resize', resize]);
for (const l of LISTENERS) l[0].addEventListener(l[1], l[2]);
